# Peach & nectarine cultivars with identification traits. REAL cultivars only; every trait comes from the cited source(s).
# Blank = not recorded in our sources (never guessed).
# Trait vocab: flesh white|yellow|red|pale (pale = creamy/lemon, sources disagree white vs yellow)
#              stone free|semi|cling   flower showy (large) | non-showy (small)   glands reniform|globose|none|mixed
#              ripe early|mid|late (relative within the season)   shape flat (peento/doughnut) when relevant
SRC={
 'N':"Nicholson, Illustrated Dictionary of Gardening (1884–88), Peach/Nectarine sorts",
 'H':"Hedrick, The Peaches of New York (NY Agric. Exp. Station, 1917)",
 'C':"Clemson University peach & nectarine cultivar descriptions (Brooks & Olmo register data)",
 'W':"NW Fruit (Western Washington Fruit Research Foundation) variety trials",
 'B':"Bernwode Fruit Trees heritage variety notes",
 'K':"Carol Klein, Grow Your Own Fruit (via allotment-garden.org)",
 'R':"RHS Plants / Southern Fruit Trees listings",
 'A':"Alden Lane Nursery variety notes",
 'U':"Utah State University Intermountain Tree Fruit Guide (nectarine table)",
 'G':"USDA-ARS Register of New Fruit & Nut Cultivars (HortScience)",
}
WALL='Victorian walled-garden variety: in Ireland it needs a warm south-facing wall or glass, as Nicholson advised for these islands.'
US='Bred for warmer North American summers: in Ireland grow it on a sunny wall or under cover and expect it to ripen later than the US timing.'
PNW='Trialled outdoors in maritime north-west Washington, whose cool wet springs are close to Irish conditions.'
PEACH=[]; NECT=[]
def _mk(L,name,src,**k):
    k={a:b for a,b in k.items() if b not in (None,'')}
    k['name']=name; k['src']='; '.join(SRC[s] for s in src); k['srcs']=src
    L.append(k)
def P(name,src,**k): _mk(PEACH,name,src,**k)
def Nn(name,src,**k): _mk(NECT,name,src,**k)

